const input = $input.first().json;

const userMessage   = input.user_message   || input.message      || "";
const daliaResponse = input.dalia_response || input.ai_response  || "";
const sessionMemory = input.session_memory || {};
const lastProduct   = sessionMemory.last_product || null;
const intention     = input.classified_intention || input.intention || "";
const city          = sessionMemory.city           || input.city   || null;
const purchaseActive = sessionMemory.purchase_active || false;
const handoffActive  = sessionMemory.handoff_active  || false;

// Señales que indican que hay algo útil para recordar
const hasProduct   = !!lastProduct;
const hasCity      = !!city;
const hasPurchase  = purchaseActive;
const hasHandoff   = handoffActive;
const hasIntent    = ["product_inquiry","purchase_intent","preference_signal",
                      "unresolved_need","handoff_request"].includes(intention);

const shouldPersist = hasProduct || hasCity || hasPurchase || hasHandoff || hasIntent;

// Determinar tipo de memoria
let memoryType = "conversation_summary";
if (hasPurchase)          memoryType = "purchase_context";
else if (hasHandoff)      memoryType = "handoff_context";
else if (hasProduct && hasIntent) memoryType = "product_interest";
else if (hasCity)         memoryType = "city_or_location";
else if (hasIntent)       memoryType = "preference";

// Calcular confianza básica
let confidence = 0.5;
if (hasProduct)  confidence += 0.2;
if (hasCity)     confidence += 0.1;
if (hasPurchase) confidence += 0.2;
if (hasIntent)   confidence += 0.1;
confidence = Math.min(confidence, 0.99);

const candidate = {
  persist:      shouldPersist,
  memory_type:  memoryType,
  confidence:   parseFloat(confidence.toFixed(2)),
  product_id:   lastProduct?.product_id   || null,
  product_name: lastProduct?.product_name || null,
  category:     lastProduct?.category     || null,
  city:         city,
  user_message: userMessage,
  dalia_response: daliaResponse,
  intention:    intention
};

return [{ json: { ...input, customer_memory_candidate: candidate } }];

const input = $input.first().json;
const c = input.customer_memory_candidate;
const ctx = input.context || {};
const userId = ctx.user_id || input.user_id || "unknown";

let parts = [];

// Base: quién es el cliente y qué hizo
if (c.memory_type === "product_interest" && c.product_name) {
  parts.push(`Cliente ${userId} mostró interés en ${c.product_name}.`);
}
if (c.memory_type === "purchase_context" && c.product_name) {
  parts.push(`Cliente ${userId} inició proceso de compra del producto ${c.product_name}.`);
}
if (c.memory_type === "handoff_context") {
  parts.push(`Cliente ${userId} solicitó atención humana por WhatsApp.`);
}
if (c.memory_type === "city_or_location" && c.city) {
  parts.push(`Cliente ${userId} mencionó ${c.city} como ciudad de entrega.`);
}
if (c.memory_type === "preference") {
  parts.push(`Cliente ${userId} mostró preferencias de compra durante la conversación.`);
}
if (c.memory_type === "conversation_summary") {
  parts.push(`Resumen de conversación con cliente ${userId}.`);
}

// Enriquecer con detalles disponibles
if (c.product_name && c.memory_type !== "product_interest") {
  parts.push(`Producto consultado: ${c.product_name}.`);
}
if (c.category) {
  parts.push(`Categoría: ${c.category}.`);
}
if (c.city && c.memory_type !== "city_or_location") {
  parts.push(`Ciudad mencionada: ${c.city}.`);
}
if (c.intention && c.intention !== "conversation_summary") {
  const intentionLabels = {
    product_inquiry:    "Consulta de producto",
    purchase_intent:    "Intención de compra",
    preference_signal:  "Señal de preferencia",
    unresolved_need:    "Necesidad no resuelta",
    handoff_request:    "Solicitud de agente humano"
  };
  const label = intentionLabels[c.intention] || c.intention;
  parts.push(`Intención detectada: ${label}.`);
}

// Agregar fragmento del mensaje del usuario para contexto semántico
if (c.user_message && c.user_message.length > 5) {
  const snippet = c.user_message.substring(0, 120);
  parts.push(`Mensaje del cliente: "${snippet}${c.user_message.length > 120 ? "..." : ""}"`);
}

const memoryText = parts.join(" ").trim();

return [{ json: { ...input, memory_text_to_embed: memoryText } }];

