const { v4: uuidv4 } = require("uuid");
const pointId = uuidv4();

const now = new Date().toISOString();

const payload = {
  business_id:     ctx.business_id     || input.business_id     || "business_demo",
  user_id:         ctx.user_id         || input.user_id         || "",
  channel:         ctx.channel         || input.channel         || "whatsapp",
  conversation_id: ctx.conversation_id || input.conversation_id || "",
  session_id:      ctx.session_id      || input.session_id      || "",
  memory_type:     c.memory_type,
  memory_text:     input.memory_text_to_embed,
  product_id:      c.product_id   || null,
  product_name:    c.product_name || null,
  category:        c.category     || null,
  city:            c.city         || null,
  source_module:   "M4",
  source_event:    "post_turn_memory",
  confidence:      c.confidence,
  created_at:      now,
  expires_at:      null
};

const memoryPoint = {
  point_id: pointId,
  payload:  payload
};

return [{ json: { ...input, customer_memory_point: memoryPoint } }];

const input = items[0]?.json || {};
const c = input.customer_memory_candidate || {};
const ctx = input.context || {};

// Determinar por qué se saltó, en base a las señales que sí se evaluaron
function buildSkipReason(candidate) {
  if (!candidate || Object.keys(candidate).length === 0) {
    return 'no_candidate_built';
  }
  if (candidate.persist === false) {
    return 'candidate_has_no_commercial_signal';
  }
  return 'unknown_skip_reason';
}

const event = {
  schema_version: 'dalia.m8.event_request.v1',
  event_name: 'customer_memory_skipped',
  event_type: 'memory',
  module: 'M4',
  status: 'skipped',
  correlation_context: {
    conversation_id: ctx.conversation_id || input.conversation_id || '',
    session_id: ctx.session_id || input.session_id || '',
    user_id: ctx.user_id || input.user_id || ''
  },
  payload: {
    reason: buildSkipReason(c),
    intention: c.intention || '',
    had_product: Boolean(c.product_name),
    had_city: Boolean(c.city),
    collection: 'dalia_customer_memory_demo'
  },
  occurred_at: new Date().toISOString()
};

return [{
  json: {
    ...input,
    m8_event_request: { event }
  }
}];

